def transform(grid):
    H = len(grid)
    W = len(grid[0])
    g = [row[:] for row in grid]

    sep = -1
    for x in range(W):
        c = g[0][x]
        if c != 0 and all(row[x] == c for row in g):
            sep = x
            break
    if sep < 0 or sep + 1 >= W:
        return g

    top, bottom = 0, H - 1
    left, right = sep + 1, W - 1

    frame_bg = g[top][left]
    marks = {}

    def add(color, kind, pos):
        if color not in (0, frame_bg):
            marks.setdefault(color, [[], [], [], []])[kind].append(pos)

    for r in range(top + 1, bottom):
        add(g[r][left], 0, r)
        add(g[r][right], 1, r)
    for c in range(left + 1, right):
        add(g[top][c], 2, c)
        add(g[bottom][c], 3, c)

    templates = []
    visited = [[False] * (sep + 1) for _ in range(H)]

    for r in range(H):
        for c in range(sep + 1):
            if visited[r][c] or g[r][c] == 0:
                continue
            color = g[r][c]
            cells = []
            stack = [(r, c)]
            visited[r][c] = True
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < sep + 1:
                        if not visited[ny][nx] and g[ny][nx] == color:
                            visited[ny][nx] = True
                            stack.append((ny, nx))
            templates.append((color, cells))

    used = set()
    for color, cells in templates:
        if color not in marks:
            continue
        rmin = min(r for r, _ in cells)
        cmin = min(c for _, c in cells)
        hmax = max(r - rmin for r, _ in cells)
        wmax = max(c - cmin for _, c in cells)
        rel = [(r - rmin, c - cmin) for r, c in cells]

        rows = list(set(marks[color][0]) | set(marks[color][1]))
        cols = list(set(marks[color][2]) | set(marks[color][3]))
        for rr in rows:
            for cc in cols:
                for dr, dc in rel:
                    y = rr - hmax // 2 + dr
                    x = cc - wmax // 2 + dc
                    if top < y < bottom and left < x < right:
                        if g[y][x] == 0 or g[y][x] == frame_bg:
                            g[y][x] = color
        used.add(id(cells))

    for color, cells in templates:
        if id(cells) in used:
            for r, c in cells:
                g[r][c] = 0

    return g
